/// Converts a memory keyword value to its keyword (eg. `dword`)
constexpr const FormatterString& get_memory_keyword(const FormatterConstants& c, std::uint32_t memory_keyword) noexcept {
	switch (memory_keyword) {
	case 0x00: return c.empty;
	case 0x01: return c.byte;
	case 0x02: return c.dword;
	case 0x03: return c.far;
	case 0x04: return c.fpuenv14;
	case 0x05: return c.fpuenv28;
	case 0x06: return c.fpustate108;
	case 0x07: return c.fpustate94;
	case 0x08: return c.oword;
	case 0x09: return c.qword;
	case 0x0A: return c.tword;
	case 0x0B: return c.word;
	case 0x0C: return c.yword;
	case 0x0D: return c.zword;
	case 0x0E: return c.mem384;
	default: ICED_UNREACHABLE();
	}
}

/// Converts a `BroadcastToKind` value to its string (eg. `1to8`)
constexpr const FormatterString& get_bcst_to_string(const FormatterConstants& c, std::uint32_t bcst_to_kind) noexcept {
	switch (bcst_to_kind) {
	case 0x00: return c.empty;
	case 0x01: return c.b1to2;
	case 0x02: return c.b1to4;
	case 0x03: return c.b1to8;
	case 0x04: return c.b1to16;
	case 0x05: return c.b1to32;
	default: ICED_UNREACHABLE();
	}
}

